@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
@Import(PurchaseRequestsIntegrationTests.Fixtures.class)
class PurchaseRequestsIntegrationTests {
 static final EmbeddedPostgres PG;
 static {try{PG=EmbeddedPostgres.builder().setPort(0).start();}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->PG.getJdbcUrl("postgres","postgres"));r.add("spring.datasource.username",()->"postgres");r.add("spring.datasource.password",()->"postgres");r.add("pawday.auth.secret-key",()->"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=");r.add("management.health.redis.enabled",()->false);r.add("management.health.rabbit.enabled",()->false);r.add("pawday.outbox.workers-enabled",()->false);r.add("pawday.outbox.consumer-enabled",()->false);r.add("pawday.search.enabled",()->false);r.add("pawday.care.workers-enabled",()->false);r.add("pawday.storage.cleanup-enabled",()->false);}
 @TestConfiguration static class Fixtures {@Bean @Primary Clock petClock(){return Clock.fixed(Instant.parse("2026-10-04T00:00:00Z"),ZoneId.of("Asia/Shanghai"));}}
 @Autowired cn.pawday.care.PetFoodService food; @Autowired cn.pawday.support.SupportInboxConsumer inbox;
 @Autowired JdbcTemplate db;@Autowired Crypto crypto;@Autowired Clock clock;@LocalServerPort int port;
 final JsonMapper json=JsonMapper.builder().build();final HttpClient http=HttpClient.newHttpClient();
 static final List<Map<String,Object>> SAMPLES=new CopyOnWriteArrayList<>();
 String tokenA,tokenB,adminToken;UUID userA,adminPrincipal,adminSession;
 static final String CAT="10000000-0000-4000-8000-000000000001",SMALL="10000000-0000-4000-8000-000000000005";
 record Response(int status,JsonNode body){JsonNode data(){return body.get("data");}String id(){return data().get("id").asString();}}
 String key(){return UUID.randomUUID().toString();}
 String consumer(){UUID user=UUID.randomUUID(),p=UUID.randomUUID();db.update("INSERT INTO app_user(id,status) VALUES (?,'ACTIVE')",user);db.update("INSERT INTO identity_principal(id,realm,user_id) VALUES (?,'CONSUMER',?)",p,user);userA=user;return session(p);}
 String session(UUID p){UUID s=UUID.randomUUID();String t=crypto.token();db.update("INSERT INTO auth_session(id,principal_id,access_token_hash,device_id,expires_at,refresh_expires_at,created_at) VALUES (?,?,?,'PET-IT',?,?,?)",s,p,crypto.hash(t),Timestamp.from(clock.instant().plusSeconds(900)),Timestamp.from(clock.instant().plusSeconds(2592000)),Timestamp.from(clock.instant()));adminSession=s;return t;}
 @BeforeEach void setup(){db.execute("TRUNCATE purchase_request_changes,purchase_requests,identity_command CASCADE");tokenB=consumer();tokenA=consumer();adminPrincipal=UUID.randomUUID();db.update("INSERT INTO identity_principal(id,realm,login_name,password_hash) VALUES (?,'ADMIN',?,?)",adminPrincipal,key(),"TEST-ONLY");UUID role=UUID.randomUUID();db.update("INSERT INTO role(id,scope_type,code,name) VALUES (?,'ADMIN',?,'Pet test')",role,key());db.update("INSERT INTO role_permission(role_id,permission_id) SELECT ?,id FROM permission WHERE code IN ('pet.taxonomy.read','pet.taxonomy.write','purchase-request.read','purchase-request.manage')",role);db.update("INSERT INTO principal_role(principal_id,role_id,realm) VALUES (?,?,'ADMIN')",adminPrincipal,role);adminToken=session(adminPrincipal);}
 String proof(){String p=crypto.token();db.update("INSERT INTO reverify_grant(token_hash,session_id,action,expires_at,created_at) VALUES (?,?,'pet.taxonomy.write',?,?)",crypto.hash(p),adminSession,Timestamp.from(clock.instant().plusSeconds(120)),Timestamp.from(clock.instant()));return p;}
 Response request(String method,String path,Object payload,String token,Map<String,String> headers){try{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).timeout(Duration.ofSeconds(20));if(token!=null)b.header("Authorization","Bearer "+token);headers.forEach(b::header);if(payload==null)b.method(method,HttpRequest.BodyPublishers.noBody());else if(payload instanceof byte[] bytes)b.method(method,HttpRequest.BodyPublishers.ofByteArray(bytes));else b.header("Content-Type","application/json").method(method,HttpRequest.BodyPublishers.ofString(json.writeValueAsString(payload)));var response=http.send(b.build(),HttpResponse.BodyHandlers.ofString());var body=json.readTree(response.body());if(!path.startsWith("/media/"))SAMPLES.add(Map.of("method",method.toLowerCase(),"path",path,"status",response.statusCode(),"response",body));return new Response(response.statusCode(),body);}catch(Exception e){throw new AssertionError(e);}}
 Response req(String method,String path,Object b,String token){return request(method,path,b,token,Map.of("Idempotency-Key",key()));}
 Map<String,Object> pet(){return new LinkedHashMap<>(Map.of("name","小爪","species_id",CAT,"sex","UNKNOWN","neutered_status","UNKNOWN","allergens",List.of(),"avoidance_notes",List.of()));}
 Response create(){var r=req("POST","/consumer/pets",pet(),tokenA);assertEquals(201,r.status(),r.body().toString());return r;}
 Response admin(String type,Map<String,Object> b){return request("POST","/admin/pet-taxonomy/"+type,b,adminToken,Map.of("Idempotency-Key",key(),"X-Reverify-Token",proof()));}
 Map<String,Object> stage(String code,Integer min,Integer max,boolean unknown,String unit){Map<String,Object>d=new LinkedHashMap<>();d.put("stage_code",code);d.put("display_name",code);d.put("min_age_value",min);d.put("max_age_value",max);d.put("age_unit",unit);d.put("is_unknown",unknown);return d;}
 Response publish(List<Map<String,Object>> stages,List<String> sources){return admin("life-stage-rules",Map.of("species_id",CAT,"source_refs",sources,"stages",stages));}
 @AfterAll static void close() throws Exception{Files.createDirectories(Path.of("target"));Files.writeString(Path.of("target/m68-contract-samples.json"),JsonMapper.builder().build().writeValueAsString(SAMPLES));Files.writeString(Path.of("target/m68-schema.json"),JsonMapper.builder().build().writeValueAsString(new org.springframework.jdbc.core.JdbcTemplate(new org.springframework.jdbc.datasource.DriverManagerDataSource(PG.getJdbcUrl("postgres","postgres"),"postgres","postgres")).queryForList("SELECT table_name,column_name,ordinal_position,udt_name,is_nullable,character_maximum_length FROM information_schema.columns WHERE table_schema='public' AND table_name NOT IN ('flyway_schema_history','m63_fixture') ORDER BY table_name,ordinal_position")));PG.close();}


 Map<String,Object> requestBody(){return Map.of("title","TEST 想买的粮","description","TEST ONLY synthetic demand","search_context",Map.of("q","不存在的合成粮","sort","PRICE_ASC","price_max_fen","30000"));}
 String requestProof(){String token=crypto.token();db.update("INSERT INTO reverify_grant(token_hash,session_id,action,expires_at,created_at) VALUES (?,?,'purchase-request.manage',?,?)",crypto.hash(token),adminSession,Timestamp.from(clock.instant().plusSeconds(120)),Timestamp.from(clock.instant()));return token;}
 Map<String,String> command(int version){return Map.of("Idempotency-Key",key(),"If-Match","\""+version+"\"");}
 Map<String,String> decisionHeaders(int v){return Map.of("Idempotency-Key",key(),"If-Match","\""+v+"\"","X-Reverify-Token",requestProof());}
 @Test void fullRequestReviewAndConsumerProgress(){var made=req("POST","/consumer/purchase-requests",requestBody(),tokenA);assertEquals(200,made.status(),made.body().toString());String id=made.id();assertEquals(1,req("GET","/consumer/purchase-requests",null,tokenA).data().size());assertEquals("TEST 想买的粮",req("GET","/consumer/purchase-requests/"+id,null,tokenA).data().get("title").asString());assertEquals(1,req("GET","/admin/purchase-requests?status=OPEN",null,adminToken).data().size());assertEquals(200,req("GET","/admin/purchase-requests/"+id,null,adminToken).status());var b=Map.of("status","REVIEWING","response","TEST reviewing, no procurement commitment");var h=decisionHeaders(0);assertEquals(200,request("POST","/admin/purchase-requests/"+id+"/decision",b,adminToken,h).status());assertEquals(200,request("POST","/admin/purchase-requests/"+id+"/decision",b,adminToken,h).status());assertEquals("REVIEWING",req("GET","/consumer/purchase-requests/"+id,null,tokenA).data().get("status").asString());assertEquals(200,request("POST","/admin/purchase-requests/"+id+"/decision",Map.of("status","RESOLVED","response","TEST answer only"),adminToken,decisionHeaders(1)).status());assertEquals(3,req("GET","/consumer/purchase-requests/"+id+"/history",null,tokenA).data().size());assertEquals(3,req("GET","/admin/purchase-requests/"+id+"/history",null,adminToken).data().size());assertEquals(409,request("POST","/consumer/purchase-requests/"+id+"/cancel",null,tokenA,command(2)).status());assertEquals(0,db.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregate_type='PURCHASE_REQUEST'",Integer.class));}
 @Test void consumerCanWithdrawAndTerminalCannotBeOverwritten(){String id=req("POST","/consumer/purchase-requests",requestBody(),tokenA).id();var h=command(0);assertEquals(200,request("POST","/consumer/purchase-requests/"+id+"/cancel",null,tokenA,h).status());assertEquals(200,request("POST","/consumer/purchase-requests/"+id+"/cancel",null,tokenA,h).status());assertEquals(409,request("POST","/admin/purchase-requests/"+id+"/decision",Map.of("status","REJECTED","response","TEST"),adminToken,decisionHeaders(1)).status());assertEquals(2,req("GET","/consumer/purchase-requests/"+id+"/history",null,tokenA).data().size());assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE purchase_request_changes SET status='OPEN' WHERE request_id=?::uuid",id));}
 @Test void foreignRealmOwnerAndPermissionBoundaries(){assertEquals(401,req("POST","/consumer/purchase-requests",requestBody(),null).status());assertEquals(403,req("POST","/consumer/purchase-requests",requestBody(),adminToken).status());String id=req("POST","/consumer/purchase-requests",requestBody(),tokenA).id();assertEquals(404,req("GET","/consumer/purchase-requests/"+id,null,tokenB).status());assertEquals(404,request("POST","/consumer/purchase-requests/"+id+"/cancel",null,tokenB,command(0)).status());assertEquals(404,req("GET","/consumer/purchase-requests/"+id+"/history",null,tokenB).status());assertEquals(0,req("GET","/consumer/purchase-requests",null,tokenB).data().size());db.update("DELETE FROM role_permission WHERE role_id IN(SELECT role_id FROM principal_role WHERE principal_id=?) AND permission_id IN(SELECT id FROM permission WHERE code LIKE 'purchase-request.%')",adminPrincipal);assertEquals(403,req("GET","/admin/purchase-requests",null,adminToken).status());}
 @Test void dedupIdempotencyAndEncryptedContent(){String k=key();var h=Map.of("Idempotency-Key",k);var a=request("POST","/consumer/purchase-requests",requestBody(),tokenA,h);assertEquals(200,a.status());assertEquals(a.id(),request("POST","/consumer/purchase-requests",requestBody(),tokenA,h).id());assertEquals(a.id(),req("POST","/consumer/purchase-requests",requestBody(),tokenA).id());var changed=new HashMap<>(requestBody());changed.put("title","TEST changed");assertEquals(409,request("POST","/consumer/purchase-requests",changed,tokenA,h).status());assertFalse(db.queryForObject("SELECT request_cipher FROM purchase_requests WHERE id=?::uuid",String.class,a.id()).contains("TEST ONLY"));assertFalse(db.queryForObject("SELECT result_json::text FROM identity_command WHERE idempotency_key=?",String.class,k).contains("想买"));assertEquals(1,db.queryForObject("SELECT count(*) FROM purchase_requests",Integer.class));}
 @Test void invalidContextVersionsAndProofRejected(){var b=new HashMap<>(requestBody());b.put("search_context",Map.of("unexpected","x"));assertEquals(400,req("POST","/consumer/purchase-requests",b,tokenA).status());b.put("search_context",Map.of("price_min_fen","200","price_max_fen","100"));assertEquals(400,req("POST","/consumer/purchase-requests",b,tokenA).status());String id=req("POST","/consumer/purchase-requests",requestBody(),tokenA).id();assertEquals(400,req("POST","/consumer/purchase-requests/"+id+"/cancel",null,tokenA).status());assertEquals(409,request("POST","/consumer/purchase-requests/"+id+"/cancel",null,tokenA,command(99)).status());assertEquals(403,request("POST","/admin/purchase-requests/"+id+"/decision",Map.of("status","REJECTED","response","TEST"),adminToken,command(0)).status());assertEquals(400,req("GET","/consumer/purchase-requests?status=BOGUS",null,tokenA).status());}
 @Test void auditFailureRollsBackRequestAndCommand(){db.execute("CREATE FUNCTION fail_request_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='purchase-request.create' THEN RAISE EXCEPTION 'TEST_ONLY'; END IF; RETURN NEW; END $$");db.execute("CREATE TRIGGER test_request_audit BEFORE INSERT ON audit_event FOR EACH ROW EXECUTE FUNCTION fail_request_audit()");try{assertEquals(503,req("POST","/consumer/purchase-requests",requestBody(),tokenA).status());assertEquals(0,db.queryForObject("SELECT count(*) FROM purchase_requests",Integer.class));assertEquals(0,db.queryForObject("SELECT count(*) FROM identity_command WHERE action='purchase-request.create'",Integer.class));}finally{db.execute("DROP TRIGGER test_request_audit ON audit_event");db.execute("DROP FUNCTION fail_request_audit()");}}
 @Test void concurrentIdenticalSubmissionsAndConflictingDecisions()throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->req("POST","/consumer/purchase-requests",requestBody(),tokenA));var b=pool.submit(()->req("POST","/consumer/purchase-requests",requestBody(),tokenA));String id=a.get().id();assertEquals(id,b.get().id());var decision=Map.of("status","REJECTED","response","TEST");var h=decisionHeaders(0);var c=pool.submit(()->request("POST","/consumer/purchase-requests/"+id+"/cancel",null,tokenA,command(0)));var d=pool.submit(()->request("POST","/admin/purchase-requests/"+id+"/decision",decision,adminToken,h));assertEquals(Set.of(200,409),Set.of(c.get().status(),d.get().status()));assertEquals(2,db.queryForObject("SELECT count(*) FROM purchase_request_changes WHERE request_id=?::uuid",Integer.class,id));}}
 @Test void dailyLimitDoesNotBlockIdempotentReplay(){for(int i=0;i<20;i++){var b=new HashMap<>(requestBody());b.put("title","TEST request "+i);assertEquals(200,req("POST","/consumer/purchase-requests",b,tokenA).status());}assertEquals(429,req("POST","/consumer/purchase-requests",requestBody(),tokenA).status());var duplicate=new HashMap<>(requestBody());duplicate.put("title","TEST request 0");assertEquals(200,req("POST","/consumer/purchase-requests",duplicate,tokenA).status());}
}
